package com.aistock.prediction.modelcatalog;
import com.aistock.prediction.comparisonai.*;import com.aistock.prediction.maas.MaasOperationGate;import com.aistock.common.BusinessException;
import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static com.aistock.prediction.comparisonai.ComparisonAiSamples.*;
@Tag("mysql") class ComparisonAiMysqlTest {
 final Instant now=Instant.parse("2026-10-13T00:00:00Z");
 static class MutableClock extends Clock {volatile Instant time;volatile Runnable onRead;MutableClock(Instant t){time=t;}public Instant instant(){Instant captured=time;if(onRead!=null)onRead.run();return captured;}public java.time.ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(java.time.ZoneId z){return this;}}
 void seed(ModelDatabaseFixture db,UUID owner,JsonNode snapshot){db.jdbc.update("INSERT INTO stock_comparison_result(comparison_id,owner_id,result_json,summary_json,source_snapshots_json,source_hash,created_at) VALUES(?,?,?,?,?,?,?)",ID.toString(),owner.toString(),snapshot.toString(),snapshot.toString(),"[]",snapshot.path("sourceHash").asText(),java.sql.Timestamp.from(now));}
 JsonNode paragraphs(ComparisonAiFacts.Facts f){var root=M.createObjectNode();var a=root.putArray("paragraphs");for(String kind:List.of("overview","readout","risk")){var keys=ComparisonAiTemplate.required(kind,f.values());var p=a.addObject().put("kind",kind).put("template",keys.stream().map(k->"{{"+k+"}}").collect(java.util.stream.Collectors.joining("。")));p.set("refs",M.valueToTree(keys));}return ComparisonAiTemplate.render(root,f,M);}
 @Test void ownerReplayCacheFailureAndStableLatest(){var db=new ModelDatabaseFixture();var u=UUID.randomUUID();var saved=saved();seed(db,u,saved);var c=new MutableClock(now);var r=new ComparisonAiRepository(db.jdbc,M,c);var in=new ComparisonAiInput(UUID.randomUUID(),ID);var f=ComparisonAiFacts.build(saved,"model",M);assertTrue(r.claim(u,in,f,now).execute());assertFalse(r.claim(u,in,f,now).execute());var first=r.complete(u,in.operationId(),paragraphs(f),null,now);assertEquals("SUCCEEDED",first.path("state").asText());assertThrows(BusinessException.class,()->r.operation(UUID.randomUUID(),in.operationId(),now));assertThrows(BusinessException.class,()->r.get(UUID.randomUUID(),UUID.fromString(first.path("explanationId").asText())));assertThrows(BusinessException.class,()->r.replay(u,new ComparisonAiInput(in.operationId(),UUID.randomUUID()),now));var cached=r.claim(u,new ComparisonAiInput(UUID.randomUUID(),ID),f,now);assertFalse(cached.execute());assertTrue(cached.cached());var second=new ComparisonAiInput(UUID.randomUUID(),ID);var changed=ComparisonAiFacts.build(saved,"new-model",M);assertTrue(r.claim(u,second,changed,now).execute());r.complete(u,second.operationId(),null,"AI_OUTPUT_INVALID",now);var view=r.view(u,ID,true,now);assertEquals(first.path("explanationId"),view.path("latest").path("explanationId"));assertEquals("FAILED",view.path("latestAttempt").path("state").asText());assertEquals(1,db.jdbc.queryForObject("SELECT COUNT(*) FROM comparison_ai_result",Integer.class));}
 @Test void sharedGateBlocksOldAndNewKindsAndReadsArePure(){for(String kind:List.of("PREDICTION_EXPLANATION","STOCK_ANALYSIS","STOCK_QUESTION")){var db=new ModelDatabaseFixture();var u=UUID.randomUUID();var s=saved();seed(db,u,s);var c=new MutableClock(now);var r=new ComparisonAiRepository(db.jdbc,M,c);var f=ComparisonAiFacts.build(s,"model",M);var in=new ComparisonAiInput(UUID.randomUUID(),ID);r.claim(u,in,f,now);var gate=new MaasOperationGate(db.jdbc);assertThrows(BusinessException.class,()->gate.lockAndAcquire(kind,UUID.randomUUID(),now));assertEquals(1,db.jdbc.queryForObject("SELECT COUNT(*) FROM comparison_ai_operation",Integer.class));r.operation(u,in.operationId(),now.plusSeconds(51));r.view(u,ID,true,now.plusSeconds(51));assertEquals("RUNNING",db.jdbc.queryForObject("SELECT state FROM comparison_ai_operation",String.class));c.time=now.plusSeconds(51);gate.lockAndAcquire(kind,UUID.randomUUID(),c.time);assertEquals("FAILED",r.operation(u,in.operationId(),c.time).path("state").asText());assertFalse(r.claim(u,in,f,c.time).execute());assertThrows(BusinessException.class,()->r.claim(u,new ComparisonAiInput(UUID.randomUUID(),ID),f,c.time));assertEquals(1,db.jdbc.queryForObject("SELECT COUNT(*) FROM comparison_ai_operation",Integer.class));}}
 @Test void expiredWorkerCannotPublishOrReleaseNewSlot(){var db=new ModelDatabaseFixture();var u=UUID.randomUUID();var s=saved();seed(db,u,s);var c=new MutableClock(now);var r=new ComparisonAiRepository(db.jdbc,M,c);var f=ComparisonAiFacts.build(s,"model",M);var a=new ComparisonAiInput(UUID.randomUUID(),ID);r.claim(u,a,f,now);c.time=now.plusSeconds(50);var b=new ComparisonAiInput(UUID.randomUUID(),ID);r.claim(u,b,f,c.time);var prior=r.complete(u,a.operationId(),paragraphs(f),null,now);assertEquals("FAILED",prior.path("state").asText());assertEquals(b.operationId().toString(),db.jdbc.queryForObject("SELECT operation_id FROM prediction_explanation_slot",String.class));assertEquals(0,db.jdbc.queryForObject("SELECT COUNT(*) FROM comparison_ai_result",Integer.class));}
 @Test void parallelSameKeyExecutesOnce()throws Exception{var db=new ModelDatabaseFixture();var u=UUID.randomUUID();var s=saved();seed(db,u,s);var r=new ComparisonAiRepository(db.jdbc,M,new MutableClock(now));var f=ComparisonAiFacts.build(s,"model",M);var in=new ComparisonAiInput(UUID.randomUUID(),ID);var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->r.claim(u,in,f,now));var b=pool.submit(()->r.claim(u,in,f,now));assertNotEquals(a.get(10,TimeUnit.SECONDS).execute(),b.get(10,TimeUnit.SECONDS).execute());assertEquals(1,db.jdbc.queryForObject("SELECT COUNT(*) FROM comparison_ai_operation",Integer.class));}finally{pool.shutdownNow();}}

 @Test void completionRollbackKeepsOperationAndNoOrphan(){var db=new ModelDatabaseFixture();var u=UUID.randomUUID();var s=saved();seed(db,u,s);var r=new ComparisonAiRepository(db.jdbc,M,new MutableClock(now));var f=ComparisonAiFacts.build(s,"model",M);var in=new ComparisonAiInput(UUID.randomUUID(),ID);r.claim(u,in,f,now);var tooLarge=paragraphs(f);((com.fasterxml.jackson.databind.node.ObjectNode)tooLarge.get(0)).put("text","x".repeat(25000));assertThrows(BusinessException.class,()->r.complete(u,in.operationId(),tooLarge,null,now));assertEquals(0,db.jdbc.queryForObject("SELECT COUNT(*) FROM comparison_ai_result",Integer.class));assertEquals("RUNNING",r.operation(u,in.operationId(),now).path("state").asText());}
 @Test void clockIsRecheckedAfterWaitingForSlotLock()throws Exception{var db=new ModelDatabaseFixture();var u=UUID.randomUUID();var s=saved();seed(db,u,s);var c=new MutableClock(now);var r=new ComparisonAiRepository(db.jdbc,M,c);var f=ComparisonAiFacts.build(s,"model",M);var in=new ComparisonAiInput(UUID.randomUUID(),ID);r.claim(u,in,f,now);var read=new CountDownLatch(1);c.onRead=read::countDown;var executor=Executors.newSingleThreadExecutor();var tx=new org.springframework.transaction.support.TransactionTemplate(new org.springframework.jdbc.datasource.DataSourceTransactionManager(db.jdbc.getDataSource()));try{var future=tx.execute(status->{db.jdbc.queryForMap("SELECT * FROM prediction_explanation_slot WHERE slot_id=1 FOR UPDATE");var work=executor.submit(()->r.complete(u,in.operationId(),paragraphs(f),null,now));try{assertTrue(read.await(3,TimeUnit.SECONDS));}catch(InterruptedException e){throw new RuntimeException(e);}c.time=now.plusSeconds(50);return work;});assertThrows(ExecutionException.class,()->future.get(5,TimeUnit.SECONDS));assertEquals(0,db.jdbc.queryForObject("SELECT COUNT(*) FROM comparison_ai_result",Integer.class));}finally{executor.shutdownNow();}}

 @Test void actualLegacyQuestionClaimAndCompletionShareComparisonSlot(){var db=new ModelDatabaseFixture();var u=UUID.randomUUID();var analysis=QuestionMysqlTest.seed(db,u);var source=new com.aistock.prediction.analysis.AnalysisRepository(db.jdbc,M).get(u,analysis);var question=new com.aistock.prediction.question.QuestionInput(UUID.randomUUID(),analysis,"风险？");var qf=com.aistock.prediction.question.QuestionFacts.build(source,question.question(),"fixture",M);var qr=new com.aistock.prediction.question.QuestionRepository(db.jdbc,M);var snapshot=saved();seed(db,u,snapshot);var r=new ComparisonAiRepository(db.jdbc,M,new MutableClock(now));var f=ComparisonAiFacts.build(snapshot,"model",M);var input=new ComparisonAiInput(UUID.randomUUID(),ID);r.claim(u,input,f,now);assertThrows(BusinessException.class,()->qr.claim(u,question,qf,now));r.complete(u,input.operationId(),null,"AI_UNAVAILABLE",now);assertTrue(qr.claim(u,question,qf,now).execute());assertThrows(BusinessException.class,()->r.claim(u,new ComparisonAiInput(UUID.randomUUID(),ID),f,now));assertEquals("FAILED",qr.complete(question.operationId(),null,"AI_UNAVAILABLE",now).path("state").asText());}
}
